import {repoRoot as root, prototypeRoot} from '../../../../2026-09-12-桌面管理器需求梳理与原型验证/01-需求分析/05-原型/原型/qa/prototype-location.mjs';
/* 源码级渲染/状态核对。无浏览器、布局引擎、网络或运行文件写入；不替代视觉 QA。 */
import fs from 'node:fs';
import vm from 'node:vm';
import assert from 'node:assert/strict';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
const here=path.dirname(fileURLToPath(import.meta.url));
const source=path.join(prototypeRoot,'原型/model-config.js');
const sectionNames=['basic','match','common','variants','sources'];
function make(){
const nodes=new Map(), listeners={}, timers=[];
let confirm=null,options={},bodyOwner=new Map(),modalTitle='',headerHeight=72,mainPadding=0;const routes=[];
// 固定几何仅模拟滚动与重排，不包含浏览器布局引擎。
function layout(){const collapsed=nodes.get('mpTemplateWorkspace')?.classList.contains('nav-collapsed'),scope=nodes.get('mpContent')?.innerHTML.includes('data-template-channel=');return Object.fromEntries(sectionNames.map((id,i)=>[id,[280,640,1280,2260,2610][i]-(collapsed&&i>=2?160:0)+(scope&&i>=2?80:0)]));}
class Node {
 constructor(id=''){this.id=id;this.dataset={};const properties=new Map();this.style={setProperty:(key,value)=>properties.set(key,value),getPropertyValue:key=>properties.get(key)||''};this.disabled=false;this.checked=false;this.indeterminate=false;this.value='';this.attributes=new Map();this.events={};const classes=new Set();this.classList={add:(...items)=>items.forEach(x=>classes.add(x)),remove:(...items)=>items.forEach(x=>classes.delete(x)),contains:x=>classes.has(x),toggle:(x,force)=>{const on=force??!classes.has(x);if(on)classes.add(x);else classes.delete(x);return on;}};this._html='';this._scrollTop=0;this.clientHeight=600;}
 setAttribute(key,value){this.attributes.set(key,String(value));if(key==='class')this.classList.add(...String(value).split(/\s+/).filter(Boolean));if(key.startsWith('data-'))this.dataset[key.slice(5).replace(/-([a-z])/g,(_,c)=>c.toUpperCase())]=String(value);}
 getAttribute(key){return this.attributes.get(key)??null;}
 get scrollHeight(){return this.id==='mpMain'?layout().sources+300:600;}
 get scrollTop(){return this._scrollTop;}
 set scrollTop(value){this._scrollTop=this.id==='mpMain'?Math.max(0,Math.min(value,this.scrollHeight-this.clientHeight)):value;}
 scrollTo(options){this.lastScroll={...options};this.scrollTop=options.top;listeners.scroll?.({target:this});}
 getBoundingClientRect(){if(this.id==='mpTemplateHeader'){const top=Math.max(100,280-headerHeight-nodes.get('mpMain').scrollTop);return {top,bottom:top+headerHeight,height:headerHeight};}const offset=layout()[this.dataset.templateSection],top=this.id==='mpMain'?100:100+(offset??0)-nodes.get('mpMain').scrollTop,next=sectionNames.indexOf(this.dataset.templateSection)+1,bottom=offset===undefined?top+600:100+(layout()[sectionNames[next]]??nodes.get('mpMain').scrollHeight)-nodes.get('mpMain').scrollTop;return {top,bottom,height:bottom-top};}
 set innerHTML(html){this._html=html;
  if(this.id==='mpContent'){nodes.delete('mpScopeAll');const tag=html.match(/<input[^>]*data-scope-all[^>]*>/)?.[0];if(tag){const node=new Node('mpScopeAll');node.checked=/\bchecked(?:\s|>)/.test(tag);node.disabled=/\bdisabled\b/.test(tag);nodes.set(node.id,node);}}
  if(['modalBody','mpContent','mpAssistantHost'].includes(this.id)){
   for(const id of bodyOwner.get(this.id)||[])nodes.delete(id);bodyOwner.set(this.id,[]);
   for(const m of html.matchAll(/<([a-z]+)[^>]*\bid="([^"]+)"[^>]*>/g)){
   const node=new Node(m[2]);node.value=/\bvalue="([^"]*)"/.exec(m[0])?.[1]||'';node.checked=/\bchecked\b/.test(m[0]);node.disabled=/\bdisabled\b/.test(m[0]);
    for(const a of m[0].matchAll(/([a-z][a-z0-9-]*)="([^"]*)"/g))node.setAttribute(a[1],a[2]);
    if(m[1]==='select')node.innerHTML=html.slice(m.index+m[0].length,html.indexOf('</select>',m.index));
    if(m[1]==='textarea')node.value=html.slice(m.index+m[0].length,html.indexOf('</textarea>',m.index)).replace(/&quot;/g,'\"').replace(/&#39;/g,"'").replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&amp;/g,'&');
    nodes.set(node.id,node);bodyOwner.get(this.id).push(node.id);
   }
   if(this.id==='mpContent'){
    this.navNodes=[...html.matchAll(/<button class="mp-nav-item"[^>]*>/g)].map(tag=>{const node=new Node();for(const a of tag[0].matchAll(/([a-z][a-z0-9-]*)="([^"]*)"/g))node.setAttribute(a[1],a[2]);return node;});
    this.fieldEditor=html.includes('data-field-editor')?new Node():null;
   }
  }
  if(this.id.startsWith('mpExternal')||this.id.startsWith('mpMatch')||this.id.startsWith('mpBatch')||this.id.startsWith('mpAgent')||this.id.startsWith('mpChannel')||this.id.startsWith('mpAdopt')||this.id.startsWith('mpExport')||this.id==='mpGenerationTemplate'||this.id==='mpGenerationSources'){
   const options=[...html.matchAll(/<option\s+([^>]*)>/g)];
   const chosen=options.find(m=>/\bselected\b/.test(m[1]))||options[0];this.value=/value="([^"]*)"/.exec(chosen?.[1]||'')?.[1]||'';
  }
 }
 get innerHTML(){return this._html;}
 addEventListener(type,fn){this.events[type]=fn;}
 matches(q){return this.id==='mpScopeAll'&&q==='[data-scope-all]';}
 select(){this.selected=true;}
 focus(options){document.activeElement=this;this.focusOptions=options;}
 setSelectionRange(start,end){this.selectionStart=start;this.selectionEnd=end;}
 closest(q){return q==='.main'?nodes.get('mpMain'):q==='.modal-mask'?nodes.get('modalMask'):null;}
 querySelector(q){return q==='[data-field-editor]'&&this.id==='mpContent'?this.fieldEditor:q.startsWith('#')?(this._html.includes('id="'+q.slice(1)+'"')?nodes.get(q.slice(1)):null):new Node();}
 querySelectorAll(q){return q==='.mp-nav-item'?this.navNodes||[]:[];}
}
for(const id of ['mpMain','mpAssistantHost','mpContent','mpSettingsContent','modal','modalBody','modalMask','modalConfirm'])nodes.set(id,new Node(id));
const document={activeElement:null,documentElement:{dataset:{route:'models',theme:'light'}},querySelector:q=>q==='#modalBody .mp-dialog'?new Node():q.startsWith('#')?nodes.get(q.slice(1))||null:q==='[data-field-editor]'?new Node():q==='[data-scope-all]'?nodes.get('mpScopeAll'):null,querySelectorAll:q=>q==='[data-scope-all]'&&nodes.has('mpScopeAll')?[nodes.get('mpScopeAll')]:[],addEventListener:(type,fn)=>{listeners[type]=fn;}};
const context={document,navigator:{},window:{location:{hash:'#models'},matchMedia:()=>({matches:false}),getComputedStyle:()=>({paddingTop:mainPadding+'px'}),addEventListener:(type,fn)=>listeners['window:'+type]=fn},JSON,Date,URL,Set,Object,String,Number,Array,console,setTimeout:fn=>timers.push(fn),toast(){},setRoute(route){routes.push(route);document.documentElement.dataset.route=route;},showSettingsSection(section){routes.push(section);},openModal(title,body,label,fn,opts){modalTitle=title;nodes.get('modalBody').innerHTML=body;nodes.get('modalMask').style.display='flex';confirm=fn;options=opts||{};},closeModal(){nodes.get('modalMask').style.display='none';confirm=null;context.window.__modalOnClose?.();}};
vm.createContext(context);vm.runInContext(fs.readFileSync(source,'utf8'),context,{filename:source});
const state=()=>context.window.modelPrototype.state(),page=()=>nodes.get('mpContent').innerHTML,dialog=()=>nodes.get('modalBody').innerHTML;
function click(action,data={}){const target={dataset:{mp:action,...data},closest(){return this;}};listeners.click({target});}
function runConfirm(){const fn=confirm;assert.equal(typeof fn,'function');fn();}
function drain(){let limit=30;while(timers.length&&limit-->0)timers.shift()();assert.ok(limit>0,'finite timers');}

 const proto=context.window.modelPrototype;
 const event=(type,selector,dataset={},value='',checked=false)=>listeners[type]({target:{dataset,value,checked,matches:q=>q===selector}});
 const meta=(key,value)=>event('input','[data-template-meta],[data-template-match]',{templateMeta:key},value);
 const match=(key,value,checked=false)=>event('change','[data-template-match]',{templateMatch:key},value,checked);
 const open=(id='gpt')=>{click('tab',{tab:'templates'});click('view-template',{id});};
 const startExternal=(range='current')=>{click('external-agent');nodes.get('mpExternalScope').value=range;runConfirm();return state().externalTask;};
 const operation=(target,content=target.content)=>({action:'revision',id:target.id,revision:target.nextRevision,baseDigest:target.baseDigest,content:JSON.parse(JSON.stringify(content)),sources:['演示来源，未检索']});
 const incoming=(task,ops)=>{click('external-result');nodes.get('mpExternalJSON').value=JSON.stringify({kind:'template-batch-result',taskId:task.taskId,operations:ops});runConfirm();};
 const configureAgent=()=>{click('agent-settings');nodes.get('mpAgentProvider').value='newapi';nodes.get('mpAgentProvider').onchange();nodes.get('mpAgentModel').value='gpt-5.4';nodes.get('mpAgentModel').onchange();runConfirm();context.closeModal();};
 const scroll=(top,target=nodes.get('mpMain'))=>{target.scrollTop=top;listeners.scroll({target});};
 return {nodes,context,state,page,dialog,click,runConfirm,drain,proto,event,meta,match,open,startExternal,operation,incoming,configureAgent,scroll,routes,resize:(height,viewport=600,padding=mainPadding,border=0)=>{headerHeight=height;mainPadding=padding;nodes.get('mpMain').clientHeight=viewport;nodes.get('mpMain').clientTop=border;listeners['window:resize']?.();}};
}
const results=[];
function check(name,fn){fn(make());results.push(name);console.log('PASS '+name);}
check('列表将自由新建与外部 Agent 并列，自动填充只在编辑器内',h=>{h.click('tab',{tab:'templates'});assert.match(h.page(),/新建模版.*外部 Agent 配置/);assert.doesNotMatch(h.page(),/data-mp="generate"/);assert.match(h.page(),/data-mp="open-template-editor"[^>]*>编辑/);const before=JSON.stringify(h.state().templates),policy=JSON.stringify(h.state().draft);h.click('open-template-editor',{id:'gpt'});assert.ok(h.state().buffers.gpt);assert.match(h.page(),/模版设置分区/);h.click('editor-section',{id:'common'});assert.match(h.page(),/data-field-editor/);assert.match(h.page(),/保存候选版本/);assert.equal(JSON.stringify(h.state().templates),before);assert.equal(JSON.stringify(h.state().draft),policy);h.click('cancel-template');h.click('new-template');assert.match(h.page(),/自由命名模型族/);assert.match(h.page(),/data-mp="generate"/);assert.doesNotMatch(h.page(),/适用族|data-template-family/);});
check('新建仅产生缓冲，返回可恢复，取消不污染库和策略',h=>{const before=h.state();h.click('new-template');const id=h.state().templateScratch.id;h.meta('name','我的私有模型族');h.match('include','glob:private-*');h.click('back-templates');assert.match(h.page(),/有未保存的新模版/);h.click('new-template');assert.equal(h.state().buffers[id].name,'我的私有模型族');h.click('cancel-template');assert.equal(h.state().templateScratch,null);assert.equal(JSON.stringify(h.state().templates),JSON.stringify(before.templates));assert.equal(JSON.stringify(h.state().draft),JSON.stringify(before.draft));});
check('新建必填匹配规则，保存后未设主版本且未自动采用',h=>{const before=h.state();h.click('new-template');h.meta('name','私有编码族');h.click('save-template');assert.match(h.nodes.get('mpTemplateError').textContent,/包含规则/);h.match('include','prefix:private-');h.click('save-template');const t=h.state().templates.at(-1);assert.equal(t.name,'私有编码族');assert.equal(t.main,0);assert.equal(t.versions.length,1);assert.deepEqual(Object.keys(t.versions[0].rules),[]);assert.equal(JSON.stringify(h.state().draft),JSON.stringify(before.draft));});
function custom(h,include,extra={}){h.click('new-template');h.meta('name','自定义测试族');h.match('include',include);for(const [k,v] of Object.entries(extra))h.match(k,typeof v==='boolean'?'':String(v),v===true);h.click('save-template');return h.state().templates.at(-1).id;}
check('精确与前缀不使用预定族枚举',h=>{const id=custom(h,'exact:vendor/coder-v2\nprefix:custom-');assert.equal(h.proto.templateMatches(id,'vendor/coder-v2'),true);assert.equal(h.proto.templateMatches(id,'vendor/coder-v2-extra'),false);assert.equal(h.proto.templateMatches(id,'CUSTOM-1'),true);});
check('通配符正确转义正则特殊字符并支持问号',h=>{const id=custom(h,'glob:vendor/m[1].coder?*');assert.equal(h.proto.templateMatches(id,'vendor/m[1].coderAX'),true);assert.equal(h.proto.templateMatches(id,'vendor/m1XcoderAX'),false);});
check('排除优先、大小写与渠道范围可组合',h=>{const id=custom(h,'glob:Qwen*',{exclude:'glob:*-embedding',caseSensitive:true,channelMode:'whitelist',channels:'newapi'});assert.equal(h.proto.templateMatches(id,'Qwen3'),true);assert.equal(h.proto.templateMatches(id,'qwen3'),false);assert.equal(h.proto.templateMatches(id,'Qwen3-embedding'),false);assert.equal(h.proto.templateMatches(id,'Qwen3','aimami'),false);});
check('零命中预览可返回，匹配预览不改白名单',h=>{const before=JSON.stringify(h.state().draft);h.click('new-template');h.match('include','glob:no-such-model-*');h.click('match-preview');assert.match(h.dialog(),/零命中/);assert.equal(JSON.stringify(h.state().draft),before);});
check('协议来自真实适配器标识，专用连接不伪装通用 API',h=>{h.open();h.click('edit-template');h.click('editor-section',{id:'common'});assert.match(h.page(),/openai-responses/);assert.match(h.page(),/ollama-native/);assert.match(h.page(),/<option disabled>claude-cli/);h.click('new-channel');assert.match(h.dialog(),/ollama-native/);});
check('模板匹配版本精确固定，改主版本不改变采用解析',h=>{h.open();h.click('edit-template');h.match('include','prefix:not-gpt-');h.click('save-template');h.click('set-main',{id:'gpt:4'});h.runConfirm();assert.equal(h.state().templates[0].main,4);assert.equal(h.proto.templateResolution('newapi','newapi::0').ref,'gpt:1');assert.equal(h.proto.templateMatches('gpt','gpt-5.4','newapi',1),true);assert.equal(h.proto.templateMatches('gpt','gpt-5.4','newapi',4),false);});
