check('编辑缓冲保留，切换版本受阻，取消后能看历史',h=>{h.open();h.click('edit-template');h.meta('description','人工未保存');const base=h.state().buffers.gpt.base,versions=JSON.stringify(h.state().templates);h.click('back-templates');h.click('open-template-editor',{id:'gpt'});assert.equal(h.state().buffers.gpt.base,base);assert.equal(h.state().buffers.gpt.description,'人工未保存');assert.equal(JSON.stringify(h.state().templates),versions);h.event('change','[data-version]',{},'1');assert.equal(h.state().buffers.gpt.description,'人工未保存');assert.match(h.page(),/data-version[^>]*disabled/);h.click('cancel-template');h.event('change','[data-version]',{},'1');assert.doesNotMatch(h.page(),/data-field-editor/);});
