check('外部单个任务含文件、完整规则和端点摘要，不含地址凭据',h=>{h.open();const task=h.startExternal();assert.equal(task.targets.length,1);assert.equal(task.files.writeCandidate,'manager-state/model-family-templates.json');assert.ok(task.targets[0].content.match);assert.equal(task.protocolCatalog.registered.length,15);const fields=task.fieldContract.content;assert.deepEqual(Array.from(fields.rules.protocol.enum),['Responses','Chat','Anthropic','Google','Ollama']);assert.deepEqual(Array.from(fields.rules.default.enum),['none','minimal','low','medium','high','xhigh','max']);assert.deepEqual(Array.from(fields.match.rule.type),['exact','prefix','glob']);assert.match(fields.rules.inheritance,/省略.*继承.*null/);assert.match(task.matchingContract.exclude,/排除优先/);assert.match(task.matchingContract.priority,/同分.*冲突/);assert.match(task.matchingContract.effects,/不加入白名单/);assert.ok(task.context.channels[0].models[0].manual);assert.deepEqual(Array.from(task.context.protocolPriority),['channelDefault','template','templateVariant','channelFamilyOverride','modelOverride']);assert.doesNotMatch(h.nodes.get('mpExternalPrompt').value,/"baseUrl"|"connection"|"keyConfigured"|"providerId"|"executionProviderRef"/);h.click('external-copy');assert.equal(h.nodes.get('mpExternalPrompt').selected,true);assert.match(h.nodes.get('mpCopyStatus').textContent,/内容已选中/);const createOnly=h.startExternal('create');assert.equal(createOnly.targets.length,0);assert.match(createOnly.fieldContract.identity.create,/全新 ID/);assert.match(createOnly.fieldContract.content.match.include,/至少一条/);assert.ok(createOnly.resultContract.operations[0].content.match.include.length);assert.deepEqual(Object.keys(createOnly.resultContract.operations[0].content.rules),[]);assert.match(h.nodes.get('mpExternalPrompt').value,/fieldContract/);});
