check('人工缓冲变动使外部任务过期，结果不覆盖新内容',h=>{h.open();h.click('edit-template');const task=h.startExternal();h.meta('description','期间编辑');h.incoming(task,[h.operation(task.targets[0])]);assert.match(h.nodes.get('mpExternalResultError').textContent,/基准已变化/);assert.equal(h.state().buffers.gpt.description,'期间编辑');});
check('预览后库变化使再次比较过期，不部分保存',h=>{h.open();const task=h.startExternal('all');h.incoming(task,task.targets.map(t=>h.operation(t)));const before=h.state().templates.map(t=>t.versions.length);h.click('set-main',{id:'gpt:3'});h.runConfirm();h.incoming(task,task.targets.map(t=>h.operation(t)));assert.match(h.nodes.get('mpExternalResultError').textContent,/基准已变化/);assert.deepEqual(h.state().templates.map(t=>t.versions.length),before);});
check('独立默认档可与继承列表同存，非法列表默认拒绝',h=>{h.open('qwen');const task=h.startExternal(),op=h.operation(task.targets[0]);op.content.rules={default:'max'};h.incoming(task,[op]);h.runConfirm();assert.equal(h.state().templates.find(t=>t.id==='qwen').versions.at(-1).rules.default,'max');const t2=h.startExternal(),bad=h.operation(t2.targets[0]);bad.content.rules={efforts:['low'],default:'high'};h.incoming(t2,[bad]);assert.match(h.nodes.get('mpExternalResultError').textContent,/默认档位/);});
check('外部协议变更仍保留锁定上下文并校验冲突高级项',h=>{h.open();let task=h.startExternal(),op=h.operation(task.targets[0]);op.content.rules.context=128000;h.incoming(task,[op]);h.runConfirm();task=h.startExternal();op=h.operation(task.targets[0]);op.content.rules.context=256000;h.incoming(task,[op]);assert.match(h.nodes.get('mpExternalResultError').textContent,/锁定的人工上下文/);op.content.rules.context=128000;op.content.rules.force='high';op.content.rules.omit=true;h.incoming(task,[op]);assert.match(h.nodes.get('mpExternalResultError').textContent,/强制档与不传参数冲突/);});
check('采用界面直接选渠道，保存才提交并等待重启',h=>{h.open();h.event('change','[data-version]',{},'3');const before=JSON.stringify(h.state().saved);h.click('adopt-version');assert.match(h.dialog(),/mpAdoptChannel-newapi/);h.nodes.get('mpAdoptChannel-newapi').checked=true;h.nodes.get('mpAdoptChannel-newapi').onchange();h.runConfirm();assert.equal(h.state().draft.providers[0].refs.gpt,'gpt:3');assert.equal(h.state().saved.providers[0].refs.gpt,'gpt:1');assert.equal(JSON.stringify(h.state().saved),before);h.click('view-draft');assert.match(h.dialog(),/gpt:3/);h.context.closeModal();h.click('save');h.runConfirm();h.drain();assert.equal(h.state().saved.providers[0].refs.gpt,'gpt:3');assert.equal(h.state().pending,true);});
check('候选比较、设主版本、归档与有依赖删除保护可演示',h=>{h.open();h.event('change','[data-version]',{},'3');h.click('compare');assert.match(h.dialog(),/default：中 → 高/);h.context.closeModal();h.click('delete-version',{id:'gpt:1'});assert.equal(h.state().templates[0].versions.length,3);h.click('delete-version',{id:'gpt:3'});assert.equal(h.state().templates[0].versions.length,2);h.click('archive-version',{id:'gpt:2'});assert.equal(h.state().templates[0].versions.find(v=>v.n===2).archived,true);});
check('按族批量配置零匹配时解释而不生成无效覆盖',h=>{h.event('change','[data-scope-all]',{},'',true);h.click('batch');h.nodes.get('mpBatchFamily').value='qwen';h.runConfirm();assert.match(h.nodes.get('mpBatchError').textContent,/先采用精确版本/);assert.ok(h.state().draft.providers.every(p=>Object.keys(p.familyOverrides).length===0));});
check('匹配白名单可勾选多个渠道，取消全部不扩大范围',h=>{h.click('new-template');h.meta('name','跨渠道自定义');h.match('include','prefix:gpt-');h.click('editor-section',{id:'match'});h.match('channelMode','whitelist');assert.match(h.page(),/data-template-channel="newapi"/);h.event('change','[data-template-channel]',{templateChannel:'newapi'},'',true);h.event('change','[data-template-channel]',{templateChannel:'aimami'},'',true);const id=h.state().templateScratch.id;assert.deepEqual(h.state().buffers[id].match.channels,['newapi','aimami']);h.event('change','[data-template-channel]',{templateChannel:'newapi'},'',false);h.event('change','[data-template-channel]',{templateChannel:'aimami'},'',false);assert.deepEqual(h.state().buffers[id].match.channels,[]);h.click('save-template');assert.equal(h.proto.templateMatches(id,'gpt-5.4','a6api'),false);});
check('匹配预览列出精确排除原因及未选停用状态，编辑名称可比较',h=>{h.click('toggle-provider',{id:'newapi'});h.click('new-template');h.meta('name','停用匹配检查');h.match('include','prefix:gpt-');h.match('exclude','exact:gpt-5.4');h.click('match-preview');assert.match(h.dialog(),/排除优先：exact:gpt-5.4/);assert.match(h.dialog(),/停用 · 已选/);assert.match(h.dialog(),/未选/);h.context.closeModal();h.open('gpt');h.click('edit-template');h.meta('name','新名称');h.click('compare');assert.match(h.dialog(),/名称：GPT · Responses → 新名称/);});

function revision(h,edit){h.open();const task=h.startExternal(),op=h.operation(task.targets[0]);edit(op.content);h.incoming(task,[op]);h.runConfirm();return op.revision;}
function adoptNewapi(h){h.click('adopt-version');h.nodes.get('mpAdoptChannel-newapi').checked=true;h.nodes.get('mpAdoptChannel-newapi').onchange();h.runConfirm();}
check('三种渠道范围空名单语义与旧字段兼容',h=>{let n=revision(h,c=>{c.match.channelMode='whitelist';c.match.channels=[];});assert.equal(h.proto.templateMatches('gpt','gpt-5.4','newapi',n),false);n=revision(h,c=>{c.match.channelMode='blacklist';c.match.channels=[];});assert.equal(h.proto.templateMatches('gpt','gpt-5.4','newapi',n),true);n=revision(h,c=>{c.match.channelMode='all';c.match.channels=['newapi'];});assert.equal(h.proto.templateMatches('gpt','gpt-5.4','aimami',n),true);n=revision(h,c=>{delete c.match.channelMode;c.match.channels=['newapi'];});assert.equal(h.proto.templateMatches('gpt','gpt-5.4','aimami',n),false);});
check('渠道黑名单排除已选但允许未来新增渠道',h=>{const n=revision(h,c=>{c.match.channelMode='blacklist';c.match.channels=['newapi'];});assert.equal(h.proto.templateMatches('gpt','gpt-5.4','newapi',n),false);assert.equal(h.proto.templateMatches('gpt','gpt-5.4','aimami',n),true);h.click('new-channel');h.nodes.get('mpChannelName').value='Future';h.nodes.get('mpChannelId').value='future';h.nodes.get('mpChannelURL').value='https://example.com/v1';h.nodes.get('mpChannelAuth').value='apikey';h.nodes.get('mpChannelKey').value='mock-key';h.runConfirm();h.nodes.get('mpChannelManual').value='gpt-5.4-mini';h.click('channel-manual');h.click('channel-select');h.runConfirm();assert.ok(h.state().draft.providers.some(p=>p.id==='future'));assert.equal(h.proto.templateMatches('gpt','gpt-5.4-mini','future',n),true);});
check('版本或后缀最长字面后缀获胜，未命中继承族通用',h=>{revision(h,c=>{c.variants=[{id:'mini',name:'轻量',suffix:'mini',rules:{default:'low'}},{id:'exact-mini',name:'5.4轻量',suffix:'gpt-5.4-mini',rules:{default:'high'}}];});adoptNewapi(h);assert.equal(h.proto.resolve('newapi','newapi::1').values.default,'high');assert.match(h.proto.resolve('newapi','newapi::1').sources.default,/5.4轻量/);assert.equal(h.proto.resolve('newapi','newapi::0').values.default,'medium');});
check('版本或后缀协议参与端点解析，模型人工例外优先',h=>{revision(h,c=>{c.variants=[{id:'mini',name:'轻量',suffix:'-mini',rules:{protocol:'Chat',default:'low'}}];});adoptNewapi(h);assert.equal(h.proto.resolveRoute('newapi','newapi::1').protocol,'Chat');assert.match(h.proto.resolveRoute('newapi','newapi::1').error,/缺少 Chat 端点/);h.click('import');h.nodes.get('mpImportJSON').value=JSON.stringify({kind:'policy',policy:{providers:[{id:'newapi',models:[{id:'gpt-5.4-mini',overrides:{protocol:'Responses',default:'high'}}]}]}});h.runConfirm();h.nodes.get('mpConflict').value='incoming';h.runConfirm();assert.equal(h.proto.resolveRoute('newapi','newapi::1').protocol,'Responses');assert.equal(h.proto.resolve('newapi','newapi::1').values.default,'high');});
check('后缀默认不区分大小写，重复后缀及合并非法默认拒绝全批',h=>{h.open();const task=h.startExternal(),op=h.operation(task.targets[0]);op.content.variants=[{id:'a',name:'a',suffix:'MINI',rules:{}},{id:'b',name:'b',suffix:'mini',rules:{}}];h.incoming(task,[op]);assert.match(h.nodes.get('mpExternalResultError').textContent,/后缀重复/);op.content.variants=[{id:'a',name:'a',suffix:'mini',rules:{efforts:['low']}}];h.incoming(task,[op]);assert.match(h.nodes.get('mpExternalResultError').textContent,/默认档位/);op.content.match.caseSensitive=true;op.content.variants=[{id:'a',name:'a',suffix:'MINI',rules:{default:'high'}},{id:'b',name:'b',suffix:'mini',rules:{default:'low'}}];h.incoming(task,[op]);h.runConfirm();adoptNewapi(h);assert.equal(h.proto.resolve('newapi','newapi::1').values.default,'low');});
check('可选型号可自行添加删除，最后一项删除后不存 variants',h=>{h.open();h.click('edit-template');h.click('editor-section',{id:'variants'});assert.match(h.page(),/暂未添加版本或后缀/);h.click('add-variant');h.nodes.get('mpVariantName').value='轻量';h.nodes.get('mpVariantSuffix').value='-mini';h.runConfirm();const id=h.state().buffers.gpt.variants[0].id;h.click('edit-variant',{id});assert.equal(h.nodes.get('mpVariantSuffix').value,'-mini');h.context.closeModal();h.click('delete-variant',{id});h.runConfirm();assert.equal(h.state().buffers.gpt.variants,undefined);h.click('save-template');assert.equal(h.state().templates[0].versions.at(-1).variants,undefined);});
check('型号随复制保存与导出导入保留，人工候选仍须确认',h=>{revision(h,c=>{c.match.channelMode='blacklist';c.match.channels=['aimami'];c.variants=[{id:'mini',name:'轻量',suffix:'-mini',rules:{default:'low'}}];});h.click('export');h.nodes.get('mpExportSource').value='template';h.runConfirm();const data=JSON.parse(h.nodes.get('mpJSON').value);h.context.closeModal();h.click('copy-template');let b=h.state().buffers[h.state().templateScratch.id];assert.equal(b.match.channelMode,'blacklist');assert.equal(b.variants[0].suffix,'-mini');h.click('cancel-template');h.open();h.click('import');h.nodes.get('mpImportJSON').value=JSON.stringify(data);h.runConfirm();assert.equal(h.state().proposal.variants[0].suffix,'-mini');h.click('accept-proposal');h.runConfirm();assert.equal(h.state().buffers.gpt.match.channelMode,'blacklist');assert.equal(h.state().buffers.gpt.variants[0].rules.default,'low');});
check('独立导入拒绝无效渠道模式与型号，不丢弃隐藏字段',h=>{h.open();h.click('import');h.nodes.get('mpImportJSON').value=JSON.stringify({kind:'template-result',rules:{},match:{include:[{type:'prefix',value:'gpt-'}],exclude:[],caseSensitive:false,priority:0,channels:[],channelMode:'bad'}});h.runConfirm();assert.match(h.nodes.get('mpImportError').textContent,/范围模式/);assert.equal(h.state().proposal,null);h.nodes.get('mpImportJSON').value=JSON.stringify({kind:'template-result',rules:{},variants:[{id:'x',name:'x',suffix:'',rules:{}}]});h.runConfirm();assert.match(h.nodes.get('mpImportError').textContent,/后缀/);});
check('外部任务含 subtype 规则和锁定值，禁止删除人工上下文型号',h=>{revision(h,c=>{c.variants=[{id:'mini',name:'轻量',suffix:'-mini',rules:{context:64000}}];});const task=h.startExternal(),op=h.operation(task.targets[0]);assert.ok(task.fieldContract.content.variants);assert.ok(task.context.lockedFields.includes('variants[*].rules.context'));assert.equal(task.targets[0].content.variants[0].rules.context,64000);delete op.content.variants;h.incoming(task,[op]);assert.match(h.nodes.get('mpExternalResultError').textContent,/版本或后缀人工上下文/);});
check('独立导入比较同样保留已锁定版本或后缀人工上下文',h=>{revision(h,c=>{c.variants=[{id:'mini',name:'轻量',suffix:'-mini',rules:{context:64000}}];});h.click('import');h.nodes.get('mpImportJSON').value=JSON.stringify({kind:'template-result',rules:{},variants:[{id:'mini',name:'轻量',suffix:'-mini',rules:{context:128000,default:'low'}}]});h.runConfirm();h.click('accept-proposal');assert.match(h.dialog(),/人工上下文已锁定/);h.runConfirm();assert.equal(h.state().buffers.gpt.variants[0].rules.context,64000);assert.equal(h.state().buffers.gpt.variants[0].rules.default,'low');h.click('import');h.nodes.get('mpImportJSON').value=JSON.stringify({kind:'template-result',rules:{},variants:[]});h.runConfirm();h.click('accept-proposal');h.runConfirm();assert.equal(h.state().buffers.gpt.variants[0].rules.context,64000);});
check('五区连续存在，锚点仅滚动且保留字段助手与路由',h=>{h.open();h.click('edit-template');h.click('generate');const field=h.nodes.get('mpTemplateDescription'),assistant=h.nodes.get('mpGenerationTarget'),before=h.page();h.meta('description','保留说明');for(const id of sectionNames)assert.ok(h.nodes.has('mpTemplateSection-'+id));h.click('editor-section',{id:'variants'});assert.equal(h.page(),before);assert.equal(h.nodes.get('mpTemplateDescription'),field);assert.equal(h.nodes.get('mpGenerationTarget'),assistant);assert.match(h.page(),/data-template-match="include"/);assert.equal(h.nodes.get('mpMain').lastScroll.behavior,'smooth');assert.equal(h.nodes.get('mpTemplateSection-variants').getBoundingClientRect().top-h.nodes.get('mpMain').getBoundingClientRect().top,84);assert.equal(h.state().editorSection,'variants');assert.equal(h.state().buffers.gpt.description,'保留说明');assert.equal(h.context.window.location.hash,'#models');h.context.window.matchMedia=()=>({matches:true});h.click('editor-section',{id:'common'});assert.equal(h.nodes.get('mpMain').lastScroll.behavior,'auto');});
check('导航收起展开保留 DOM 和重排后的可见锚点',h=>{h.open();h.click('edit-template');h.click('editor-section',{id:'common'});const main=h.nodes.get('mpMain'),section=h.nodes.get('mpTemplateSection-common'),field=h.nodes.get('mpMatchInclude'),offset=section.getBoundingClientRect().top-main.getBoundingClientRect().top,top=main.scrollTop;h.click('toggle-editor-nav');assert.equal(h.state().editorNavCollapsed,true);assert.ok(h.nodes.get('mpTemplateWorkspace').classList.contains('nav-collapsed'));assert.equal(h.nodes.get('mpTemplateNavToggle').getAttribute('aria-expanded'),'false');assert.equal(h.nodes.get('mpMatchInclude'),field);assert.equal(section.getBoundingClientRect().top-main.getBoundingClientRect().top,offset);assert.notEqual(main.scrollTop,top);h.click('toggle-editor-nav');assert.equal(h.state().editorNavCollapsed,false);assert.equal(h.nodes.get('mpTemplateNavToggle').getAttribute('aria-expanded'),'true');assert.equal(main.scrollTop,top);assert.equal(h.state().editorSection,'common');});
check('手动页面滚动高亮当前区，底部最后区且忽略助手滚动',h=>{h.open();h.click('edit-template');const main=h.nodes.get('mpMain');for(const [top,id] of [[0,'basic'],[628,'match'],[1268,'common'],[2248,'variants'],[main.scrollHeight,'sources']]){h.scroll(top);assert.equal(h.state().editorSection,id);const current=h.nodes.get('mpContent').querySelectorAll('.mp-nav-item').filter(n=>n.getAttribute('aria-current')==='location');assert.equal(current.length,1);assert.equal(current[0].dataset.id,id);}h.scroll(0,h.nodes.get('mpAssistantHost'));assert.equal(h.state().editorSection,'sources');h.context.document.documentElement.dataset.route='settings';h.scroll(0);assert.equal(h.state().editorSection,'sources');});
check('同编辑器重绘保留可见锚点，所有分区的字段持续绑定',h=>{h.open();h.click('edit-template');h.meta('description','保留说明');h.click('editor-section',{id:'variants'});const main=h.nodes.get('mpMain'),offset=h.nodes.get('mpTemplateSection-variants').getBoundingClientRect().top-main.getBoundingClientRect().top;h.nodes.get('mpMatchChannelMode').focus();h.match('channelMode','blacklist');assert.equal(h.nodes.get('mpTemplateSection-variants').getBoundingClientRect().top-main.getBoundingClientRect().top,offset);assert.equal(h.state().editorSection,'variants');assert.equal(h.context.document.activeElement.id,'mpMatchChannelMode');assert.equal(h.context.document.activeElement.focusOptions.preventScroll,true);assert.equal(h.nodes.get('mpTemplateDescription').value,'保留说明');assert.equal(h.state().buffers.gpt.match.channelMode,'blacklist');assert.equal(typeof h.nodes.get('mpContent').fieldEditor.events.change,'function');h.proto.render();assert.equal(h.nodes.get('mpTemplateSection-variants').getBoundingClientRect().top-main.getBoundingClientRect().top,offset);h.open('claude');h.click('edit-template');assert.equal(main.scrollTop,0);assert.equal(h.state().editorSection,'basic');});
check('悬浮 Agent 不占 modal，收起保留输入且可操作页面',h=>{h.open();h.click('edit-template');h.click('generate');assert.notEqual(h.nodes.get('modalMask').style.display,'flex');assert.match(h.nodes.get('mpAssistantHost').innerHTML,/aria-modal="false"/);h.event('input','[data-assistant-input]',{},'待发提示');h.click('assistant-close');h.click('generate');assert.equal(h.nodes.get('mpGenerationTarget').value,'待发提示');h.click('editor-section',{id:'match'});h.match('include','prefix:manual-');assert.equal(h.state().buffers.gpt.match.include[0].value,'manual-');assert.equal(h.nodes.get('mpGenerationTarget').value,'待发提示');});
check('生成版本或后缀只提议子配置，接受不改族通用默认',h=>{h.open();h.click('edit-template');h.configureAgent();h.click('generate');h.nodes.get('mpGenerationTarget').value='添加型号后缀 gpt-5.4-mini，默认低档';h.click('generate-run');h.drain();assert.equal(h.state().proposal.variants[0].rules.default,'low');assert.equal(h.state().proposal.rules.default,'medium');h.click('accept-proposal');h.runConfirm();assert.equal(h.state().buffers.gpt.variants[0].suffix,'gpt-5.4-mini');assert.equal(h.state().buffers.gpt.rules.default,'medium');});
check('晚回期间手动型号变动保留，切目标不切页或串输入',h=>{h.open();h.click('edit-template');h.configureAgent();h.click('generate');h.nodes.get('mpGenerationTarget').value='后缀 mini，默认低档';h.click('generate-run');h.click('add-variant');h.nodes.get('mpVariantName').value='人工';h.nodes.get('mpVariantSuffix').value='manual';h.runConfirm();h.open('claude');h.click('edit-template');h.click('generate');h.event('input','[data-assistant-input]',{},'Claude 要求');h.drain();assert.equal(h.state().proposal.id,'gpt');assert.equal(h.nodes.get('mpGenerationTarget').value,'Claude 要求');h.open('gpt');h.click('generate');h.click('accept-proposal');assert.match(h.dialog(),/人工修改冲突/);h.runConfirm();assert.equal(h.state().buffers.gpt.variants[0].suffix,'manual');});
check('助手异步重绘保留后续输入的焦点和光标',h=>{h.open();h.click('edit-template');h.configureAgent();h.click('generate');h.nodes.get('mpGenerationTarget').value='默认高档';h.click('generate-run');const field=h.nodes.get('mpGenerationTarget');h.event('input','[data-assistant-input]',{},'下一轮提示');field.focus();field.setSelectionRange(2,3);h.drain();assert.equal(h.context.document.activeElement.id,'mpGenerationTarget');assert.equal(h.nodes.get('mpGenerationTarget').value,'下一轮提示');assert.equal(h.nodes.get('mpGenerationTarget').selectionStart,2);assert.equal(h.nodes.get('mpGenerationTarget').selectionEnd,3);});
check('导航操作只出现一次，预览比较更多不改变候选或渠道',h=>{h.open();h.click('edit-template');const page=h.page(),nav=page.match(/<nav class="mp-template-nav"[\s\S]*?<\/nav>/)[0],before=h.state();for(const action of ['match-preview','compare','template-more']){assert.equal(page.split('data-mp="'+action+'"').length-1,1);assert.match(nav,new RegExp('data-mp="'+action+'"'));}assert.doesNotMatch(page,/mp-detail-actions/);h.click('toggle-editor-nav');assert.match(h.page(),/aria-label="匹配预览"/);h.click('match-preview');assert.match(h.dialog(),/命中/);h.context.closeModal();h.click('compare');assert.match(h.dialog(),/主版本/);h.context.closeModal();h.click('template-more');assert.match(h.dialog(),/复制模版/);assert.equal(JSON.stringify(h.state().buffers),JSON.stringify(before.buffers));assert.equal(JSON.stringify(h.state().templates),JSON.stringify(before.templates));assert.equal(JSON.stringify(h.state().draft),JSON.stringify(before.draft));h.context.closeModal();h.click('cancel-template');h.click('new-template');const compare=h.page().match(/<button[^>]*data-mp="compare"[^>]*>/)[0];assert.match(compare,/disabled/);assert.match(compare,/title="尚无主版本可比较"/);assert.equal(compare.split('title=').length-1,1);});
check('助手标题模型入口保存设置后保持未发输入与资料锁',h=>{h.open();h.click('edit-template');h.click('generate');let html=h.nodes.get('mpAssistantHost').innerHTML,header=html.match(/<header>[\s\S]*?<\/header>/)[0];assert.match(header,/选择执行模型/);assert.doesNotMatch(header,/GPT · Responses/);const close=header.match(/<button[^>]*data-mp="assistant-close"[\s\S]*?<\/button>/)[0];assert.match(close,/aria-label="收起 Agent 对话"/);assert.match(close,/<svg/);assert.doesNotMatch(close,/>收起</);assert.match(html,/data-mp="generate-run"[^>]*disabled/);h.nodes.get('mpGenerationTarget').value='未发送的型号要求';h.event('input','[data-assistant-input]',{},'未发送的型号要求');h.event('change','[data-assistant-sources]',{},'search');h.event('change','[data-lock-field]',{},'',false);h.configureAgent();assert.equal(h.nodes.get('mpGenerationTarget').value,'未发送的型号要求');assert.equal(h.nodes.get('mpGenerationSources').value,'search');assert.equal(h.nodes.get('mpAssistantLock').checked,false);html=h.nodes.get('mpAssistantHost').innerHTML;header=html.match(/<header>[\s\S]*?<\/header>/)[0];assert.match(header,/gpt-5.4/);assert.match(header,/配置执行模型：NewApi/);assert.doesNotMatch(html,/mp-generation-executor/);assert.match(html,/data-mp="generate-run"[^>]*aria-label="发送对话"/);assert.doesNotMatch(html,/data-mp="generate-run"[^>]*disabled/);h.click('assistant-close');h.click('generate');assert.equal(h.nodes.get('mpGenerationSources').value,'search');assert.equal(h.nodes.get('mpGenerationTarget').value,'未发送的型号要求');});
check('同一发送入口持续纠偏，对话角色区保留且建议待比较',h=>{h.open();h.click('edit-template');h.configureAgent();h.click('generate');const before=h.state();for(const message of ['默认高档','默认低档']){h.nodes.get('mpGenerationTarget').value=message;h.click('generate-run');assert.equal(h.nodes.get('mpGenerationTarget').value,'');h.drain();const html=h.nodes.get('mpAssistantHost').innerHTML;assert.match(html,/role="log" aria-live="polite"/);assert.match(html,/mp-message-role">你/);assert.match(html,/mp-message-role">Agent/);assert.match(html,/data-mp="generate-run"[^>]*>[\s\S]*?<span>发送<\/span>/);assert.match(html,/查看并接受/);}assert.equal(h.state().conversation.length,4);assert.equal(h.state().proposal.rules.default,'low');assert.equal(JSON.stringify(h.state().buffers),JSON.stringify(before.buffers));assert.equal(JSON.stringify(h.state().templates),JSON.stringify(before.templates));assert.equal(JSON.stringify(h.state().draft),JSON.stringify(before.draft));h.click('accept-proposal');h.runConfirm();assert.equal(h.state().buffers.gpt.rules.default,'low');assert.equal(JSON.stringify(h.state().saved),JSON.stringify(before.saved));});
check('助手晚回保留聊天滚动光标及主页面锚点',h=>{h.open();h.click('edit-template');h.configureAgent();h.click('generate');h.click('editor-section',{id:'variants'});const main=h.nodes.get('mpMain'),top=main.scrollTop;h.nodes.get('mpGenerationTarget').value='默认高档';h.click('generate-run');h.nodes.get('mpAssistantConversation').scrollTop=72;h.event('input','[data-assistant-input]',{},'下一轮纠偏');const field=h.nodes.get('mpGenerationTarget');field.focus();field.setSelectionRange(1,4);h.drain();assert.equal(h.nodes.get('mpAssistantConversation').scrollTop,72);assert.equal(h.nodes.get('mpGenerationTarget').value,'下一轮纠偏');assert.equal(h.context.document.activeElement.id,'mpGenerationTarget');assert.equal(h.context.document.activeElement.focusOptions.preventScroll,true);assert.equal(h.nodes.get('mpGenerationTarget').selectionStart,1);assert.equal(h.nodes.get('mpGenerationTarget').selectionEnd,4);assert.equal(main.scrollTop,top);assert.equal(h.state().editorSection,'variants');});
check('放大还原仅改尺寸，输入光标聊天与正文位置保留',h=>{h.open();h.click('edit-template');h.click('generate');h.click('editor-section',{id:'common'});h.event('input','[data-assistant-input]',{},'保留未发对话');const panel=h.nodes.get('mpAssistantPanel'),input=h.nodes.get('mpGenerationTarget'),chat=h.nodes.get('mpAssistantConversation'),main=h.nodes.get('mpMain'),top=main.scrollTop;input.value='保留未发对话';input.setSelectionRange(2,5);chat.scrollTop=72;assert.equal(h.state().assistantMaximized,false);for(const expanded of [true,false]){h.click('assistant-size');assert.equal(h.state().assistantMaximized,expanded);assert.equal(h.nodes.get('mpAssistantPanel'),panel);assert.equal(h.nodes.get('mpGenerationTarget'),input);assert.equal(h.nodes.get('mpAssistantConversation'),chat);assert.equal(input.value,'保留未发对话');assert.equal(input.selectionStart,2);assert.equal(input.selectionEnd,5);assert.equal(chat.scrollTop,72);assert.equal(main.scrollTop,top);assert.equal(panel.classList.contains('is-maximized'),expanded);assert.equal(h.nodes.get('mpAssistantHost').classList.contains('assistant-maximized'),expanded);const control=h.nodes.get('mpAssistantSizeToggle');assert.equal(control.getAttribute('aria-label'),expanded?'还原 Agent 对话':'放大 Agent 对话');assert.equal(control.getAttribute('aria-pressed'),String(expanded));assert.equal(h.context.document.activeElement,control);assert.equal(control.focusOptions.preventScroll,true);}});
check('全屏收起后记住尺寸并回到入口，关闭态忽略尺寸操作',h=>{h.open();h.click('edit-template');h.click('generate');h.event('input','[data-assistant-input]',{},'尚未发送');const before=h.state();h.click('assistant-size');h.click('assistant-close');assert.equal(h.state().assistantOpen,false);assert.equal(h.state().assistantMaximized,true);assert.equal(h.nodes.has('mpAssistantPanel'),false);assert.equal(h.nodes.get('mpAssistantHost').classList.contains('assistant-maximized'),false);assert.equal(h.context.document.activeElement.id,'mpTemplateAgentAction');h.click('assistant-size');assert.equal(h.state().assistantMaximized,true);h.click('generate');assert.ok(h.nodes.get('mpAssistantPanel').classList.contains('is-maximized'));assert.equal(h.nodes.get('mpGenerationTarget').value,'尚未发送');h.click('assistant-size');h.click('assistant-close');h.click('generate');assert.equal(h.nodes.get('mpAssistantPanel').classList.contains('is-maximized'),false);for(const key of ['draft','saved','templates','buffers'])assert.equal(JSON.stringify(h.state()[key]),JSON.stringify(before[key]));});
check('放大期间发送和异步重绘保留尺寸后可还原继续对话',h=>{h.open();h.click('edit-template');h.configureAgent();h.click('generate');h.click('assistant-size');h.nodes.get('mpGenerationTarget').value='默认高档';h.click('generate-run');assert.ok(h.nodes.get('mpAssistantPanel').classList.contains('is-maximized'));h.event('input','[data-assistant-input]',{},'下轮要求');const input=h.nodes.get('mpGenerationTarget');input.focus();input.setSelectionRange(1,3);h.nodes.get('mpAssistantConversation').scrollTop=84;h.drain();assert.ok(h.nodes.get('mpAssistantPanel').classList.contains('is-maximized'));assert.equal(h.nodes.get('mpAssistantSizeToggle').getAttribute('aria-label'),'还原 Agent 对话');assert.equal(h.nodes.get('mpGenerationTarget').value,'下轮要求');assert.equal(h.context.document.activeElement.id,'mpGenerationTarget');assert.equal(h.nodes.get('mpGenerationTarget').selectionStart,1);assert.equal(h.nodes.get('mpAssistantConversation').scrollTop,84);assert.equal(h.state().conversation.length,2);h.click('assistant-size');assert.equal(h.state().conversation.length,2);assert.equal(h.nodes.get('mpGenerationTarget').value,'下轮要求');h.nodes.get('mpGenerationTarget').value='默认低档';h.click('generate-run');h.drain();assert.equal(h.state().conversation.length,4);assert.equal(h.nodes.get('mpAssistantPanel').classList.contains('is-maximized'),false);});
check('尺寸为窗口内偏好，切模版与新建继续隔离输入目标',h=>{h.open();h.click('edit-template');h.click('generate');h.click('assistant-size');h.event('input','[data-assistant-input]',{},'GPT 待发');h.open('claude');h.click('edit-template');h.click('generate');assert.ok(h.nodes.get('mpAssistantPanel').classList.contains('is-maximized'));assert.equal(h.nodes.get('mpGenerationTarget').value,'');h.event('input','[data-assistant-input]',{},'Claude 待发');h.click('new-template');assert.equal(h.state().assistantOpen,false);assert.equal(h.nodes.get('mpAssistantHost').classList.contains('assistant-maximized'),false);h.click('generate');assert.ok(h.nodes.get('mpAssistantPanel').classList.contains('is-maximized'));assert.equal(h.nodes.get('mpGenerationTarget').value,'');h.click('cancel-template');h.open('gpt');h.click('generate');assert.equal(h.nodes.get('mpGenerationTarget').value,'GPT 待发');assert.equal(h.state().assistantInputs.claude,'Claude 待发');});
check('左侧 Agent 唯一入口首位，开合与再次打开保留输入和状态',h=>{
 h.click('tab',{tab:'templates'});h.click('open-template-editor',{id:'gpt'});
 const page=h.page(),actions=[...page.matchAll(/class="btn ghost mp-nav-action" data-mp="([^"]+)"/g)].map(m=>m[1]);
 assert.deepEqual(actions,['generate','match-preview','compare','template-more','settings']);
 assert.equal(page.split('data-mp="generate"').length-1,1);
 assert.doesNotMatch(page,/mp-assistant-entry|data-mp="more"/);
 assert.equal(h.nodes.get('mpAssistantHost').innerHTML,'');
 assert.equal(h.nodes.get('mpTemplateAgentAction').getAttribute('aria-expanded'),'false');
 h.click('generate');
 assert.equal(h.nodes.get('mpTemplateAgentAction').getAttribute('aria-expanded'),'true');
 assert.doesNotMatch(h.nodes.get('mpAssistantHost').innerHTML,/mpAssistantLauncher|iframe|assistant-toggle/);
 h.event('input','[data-assistant-input]',{},'待发问题');h.click('generate');
 assert.equal(h.nodes.get('mpGenerationTarget').value,'待发问题');
 h.click('assistant-close');
 assert.equal(h.nodes.get('mpAssistantHost').innerHTML,'');
 assert.equal(h.nodes.get('mpTemplateAgentAction').getAttribute('aria-expanded'),'false');
 assert.equal(h.context.document.activeElement.id,'mpTemplateAgentAction');
 assert.equal(h.context.document.activeElement.focusOptions.preventScroll,true);
 h.click('generate');assert.equal(h.nodes.get('mpGenerationTarget').value,'待发问题');
});
check('设置迁到导航后仍打开模型设置，列表和渠道保留全局操作',h=>{
 h.click('tab',{tab:'templates'});h.click('open-template-editor',{id:'gpt'});const before=h.state();
 assert.equal(h.page().split('data-mp="settings"').length-1,1);
 h.click('settings');assert.deepEqual(h.routes,['settings','models']);
 for(const key of ['draft','saved','templates','buffers'])assert.equal(JSON.stringify(h.state()[key]),JSON.stringify(before[key]));
 h.context.document.documentElement.dataset.route='models';h.click('back-templates');
 for(const action of ['settings','more'])assert.equal(h.page().split('data-mp="'+action+'"').length-1,1);
 h.click('tab',{tab:'channels'});
 for(const action of ['settings','more'])assert.equal(h.page().split('data-mp="'+action+'"').length-1,1);
});
check('标题唯一名称输入，修改只进候选，返回恢复且取消撤销',h=>{
 h.click('tab',{tab:'templates'});h.click('open-template-editor',{id:'gpt'});const before=h.state(),page=h.page();
 assert.equal(page.split('id="mpTemplateName"').length-1,1);
 const title=page.slice(page.indexOf('<header id="mpTemplateHeader"'),page.indexOf('</header>')+9);
 for(const action of ['back-templates','version-menu'])assert.match(title,new RegExp('data-mp="'+action+'"'));
 assert.match(title,/id="mpTemplateName"/);
 const back=title.match(/<button[^>]*data-mp="back-templates"[\s\S]*?<\/button>/)[0];
 assert.match(back,/aria-label="返回模版列表"/);assert.match(back,/<svg/);assert.doesNotMatch(back,/← 模版列表/);
 const basic=page.slice(page.indexOf('id="mpTemplateSection-basic"'),page.indexOf('id="mpTemplateSection-match"'));
 assert.doesNotMatch(basic,/data-template-meta="name"/);
 const field=h.nodes.get('mpTemplateName');field.value='我的编码模型族';h.meta('name',field.value);
 assert.equal(h.state().buffers.gpt.name,field.value);assert.equal(h.nodes.get('mpTemplateName'),field);
 assert.equal(JSON.stringify(h.state().templates),JSON.stringify(before.templates));
 assert.equal(JSON.stringify(h.state().draft),JSON.stringify(before.draft));
 h.click('back-templates');h.click('tab',{tab:'templates'});h.click('open-template-editor',{id:'gpt'});
 assert.equal(h.nodes.get('mpTemplateName').value,'我的编码模型族');
 h.click('cancel-template');assert.equal(h.state().buffers.gpt,undefined);
 assert.equal(JSON.stringify(h.state().templates),JSON.stringify(before.templates));
});
check('已存标题点击即编辑选中，空名称拒绝，保存新增候选且保留主引用',h=>{
 h.open();const before=h.state();assert.match(h.page(),/data-mp="edit-template-name"/);
 h.click('edit-template-name');assert.ok(h.state().buffers.gpt);
 const field=h.nodes.get('mpTemplateName');assert.equal(h.context.document.activeElement,field);
 assert.equal(field.focusOptions.preventScroll,true);assert.equal(field.selected,true);
 h.meta('name','   ');h.click('save-template');assert.match(h.nodes.get('mpTemplateError').textContent,/名称/);
 assert.equal(JSON.stringify(h.state().templates),JSON.stringify(before.templates));
 h.meta('name','重命名的编码族');h.click('save-template');const template=h.state().templates[0];
 assert.equal(template.name,'重命名的编码族');assert.equal(template.versions.length,before.templates[0].versions.length+1);
 assert.equal(template.main,before.templates[0].main);assert.equal(template.versions.at(-1).status,'候选');
 assert.equal(JSON.stringify(h.state().draft),JSON.stringify(before.draft));assert.equal(h.state().buffers.gpt,undefined);
});
check('测量标题高度让锚点避让，窗口变窄后按新高度跟踪分区',h=>{
 h.click('tab',{tab:'templates'});h.click('open-template-editor',{id:'gpt'});const main=h.nodes.get('mpMain'),host=h.nodes.get('mpContent');
 assert.equal(host.style.getPropertyValue('--mp-editor-offset'),'84px');
 assert.equal(host.style.getPropertyValue('--mp-editor-nav-height'),'504px');
 for(const height of [116,72]){
  h.resize(height,500);h.click('editor-section',{id:'common'});
  assert.equal(h.nodes.get('mpTemplateSection-common').getBoundingClientRect().top-main.getBoundingClientRect().top,height+12);
  assert.equal(host.style.getPropertyValue('--mp-editor-offset'),height+12+'px');
  assert.equal(host.style.getPropertyValue('--mp-editor-nav-height'),500-height-24+'px');
  assert.equal(h.state().editorSection,'common');
  h.scroll(1280-height-25);assert.equal(h.state().editorSection,'match');
  h.scroll(1280-height-24);assert.equal(h.state().editorSection,'common');
 }
 h.context.window.matchMedia=()=>({matches:true});h.click('editor-section',{id:'match'});
 assert.equal(main.lastScroll.behavior,'auto');
});
check('标题固定抵消内容区顶部内距，锚点仍避让标题与边框',h=>{
 h.open();const host=h.nodes.get('mpContent'),main=h.nodes.get('mpMain');
 for(const padding of [20,10,0]){
  h.resize(72,600,padding,1);
  assert.equal(host.style.getPropertyValue('--mp-editor-top'),-padding+'px');
  assert.equal(host.style.getPropertyValue('--mp-editor-nav-top'),84-padding+'px');
  assert.equal(host.style.getPropertyValue('--mp-editor-offset'),'85px');
 }
 h.resize(116,500,20,1);h.click('edit-template');h.click('editor-section',{id:'common'});
 assert.equal(host.style.getPropertyValue('--mp-editor-top'),'-20px');
 assert.equal(host.style.getPropertyValue('--mp-editor-nav-top'),'108px');
 assert.equal(host.style.getPropertyValue('--mp-editor-offset'),'129px');
 assert.equal(host.style.getPropertyValue('--mp-editor-nav-height'),'360px');
 assert.equal(h.nodes.get('mpTemplateSection-common').getBoundingClientRect().top-main.getBoundingClientRect().top,129);
 const before=JSON.stringify(h.state().buffers);h.resize(72,600,10,1);
 assert.equal(host.style.getPropertyValue('--mp-editor-top'),'-10px');
 assert.equal(host.style.getPropertyValue('--mp-editor-nav-top'),'74px');
 assert.equal(JSON.stringify(h.state().buffers),before);
});
